ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| regex("(?i)(Login Data|Local State)", field=CommandLine)
| regex("(?i)(Google\\\\Chrome\\\\User Data|Microsoft\\\\Edge\\\\User Data|BraveSoftware\\\\Brave-Browser\\\\User Data|Chromium\\\\User Data)", field=CommandLine)
| NOT (ImageFileName=/\\(chrome|msedge|brave|firefox|opera|chromium)\.exe$/i)
| NOT (ParentBaseFileName=/^(chrome|msedge|brave|firefox|opera|chromium)\.exe$/i)
| NOT (UserName=/\$$/)
| QilinSignals := ""
| case {
    regex("(?i)(taskkill|Stop-Process).*chrome", field=CommandLine) | QilinSignals := concat([QilinSignals, "kills_browser "]);
    * | QilinSignals := QilinSignals
  }
| case {
    regex("(?i)(Copy-Item|xcopy|robocopy|\\[IO\\.File\\]::Copy)", field=CommandLine) | QilinSignals := concat([QilinSignals, "copies_artifact "]);
    * | QilinSignals := QilinSignals
  }
| case {
    ParentBaseFileName=/^gpscript\.exe$/i | QilinSignals := concat([QilinSignals, "gpo_pushed "]);
    * | QilinSignals := QilinSignals
  }
| groupBy([aid, ComputerName, UserName, ImageFileName, ParentBaseFileName, CommandLine, QilinSignals], function=count())
